import{_ as t,o,c as s,a0 as i}from"./chunks/framework.ChlVJx0I.js";const u=JSON.parse('{"title":"/ctx shows the default base prompt as split rows","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0021-ctx-shows-the-base-prompt-as-split-rows.md","filePath":"adr/0021-ctx-shows-the-base-prompt-as-split-rows.md","lastUpdated":1789777524000}'),a={name:"adr/0021-ctx-shows-the-base-prompt-as-split-rows.md"};function r(n,e,l,p,d,h){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="ctx-shows-the-default-base-prompt-as-split-rows" tabindex="-1">/ctx shows the default base prompt as split rows <a class="header-anchor" href="#ctx-shows-the-default-base-prompt-as-split-rows" aria-label="Permalink to &quot;/ctx shows the default base prompt as split rows&quot;">​</a></h1><p>The /ctx report lumped the whole default base prompt into one row, so the Prompt snippets and Prompt guidelines that tools register were invisible as such: their cost was in the token count, but a reader could not tell which guideline or snippet it was, or who registered it.</p><p>The default base prompt now renders as separate rows: one <code>base prompt</code> row holding the boilerplate (the identity line, the custom-tools line, and the pi documentation block), one <code>available tools</code> row carrying all Prompt snippets, and one row per Prompt guideline, each attributed to its source (<code>builtin</code> for pi&#39;s default bullets, <code>extension</code> for the rest). Token totals do not change: the total still estimates the prompt as the one unit the provider sees, and the report total of a session is unchanged. A custom prompt stays a single row.</p><p>The governing invariant: the section texts concatenate to the exact base prompt. Prompt-injection detection compares the sent system prompt with that concatenation, so an unmodified session must still report no injection and an extension-modified prompt must still be detected. The boilerplate therefore lives in the gaps the split rows fill: it is three section pieces under one key, and the report merges them into the single <code>base prompt</code> row.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>One row, unchanged.</strong> Simplest, but the snippet and guideline cost stays invisible.</li><li><strong>Split rows without the exact-concatenation invariant.</strong> Simpler row construction, but injection detection would need a second, parallel reconstruction and the two could drift.</li><li><strong>Split rows with the invariant (chosen).</strong> The boilerplate is stored around the split pieces; the merge is a single-key join at report time.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The row kind set gains <code>tools</code> and <code>guideline</code>; both carry a dash in the usage columns, like the other section rows.</li><li>The report row for the boilerplate holds the boilerplate text with the snippet and guideline bullets removed; expanding it shows that text, not the full prompt.</li><li>A registered guideline identical to a pi default bullet keeps the <code>builtin</code> source (it is the default bullet, and dedup keeps the first occurrence in prompt order).</li></ul>',8)])])}const m=t(a,[["render",r]]);export{u as __pageData,m as default};
